import {validateDataset,splitDataset,trainClassifier,predict,evaluate,captionsExport,buildOutline,validateBackup} from './core.js';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nav=[['home','◫','Overview'],['projects','▤','My projects'],['tools','▦','All tools'],['director','✧','Creative director'],['studio','▧','Design studio'],['video','▷','Video editor'],['models','⬡','Model lab'],['channel','⊙','YouTube channel']];
const tools=[{id:'studio',icon:'▧',title:'Thumbnail studio',desc:'Make the first impression count.',tag:'CANVAS',color:'purple'},{id:'video',icon:'▷',title:'Video editor',desc:'Trim the noise. Keep the story.',tag:'LOCAL',color:'amber'},{id:'scripts',icon:'✧',title:'Script workspace',desc:'Turn your big idea into a clear story.',tag:'TEMPLATES',color:'green'},{id:'captions',icon:'☷',title:'Caption creator',desc:'Make every word more accessible.',tag:'SRT / VTT',color:'purple'},{id:'models',icon:'⬡',title:'Model lab',desc:'Train a text classifier on your own data.',tag:'LOCAL TRAINING',color:'green'},{id:'channel',icon:'⊙',title:'YouTube connection',desc:'Your channel, with explicit permission.',tag:'SETUP REQUIRED',color:'amber'},{id:'director',icon:'⌘',title:'Production planner',desc:'A simple path from idea to export.',tag:'WORKFLOW',color:'purple'},{id:'projects',icon:'▤',title:'Project library',desc:'Keep your ideas and edits together.',tag:'LOCAL SAVE',color:'green'}];
let state={projects:[],models:[],settings:{clientId:''},script:{topic:'',format:'YouTube explainer',audience:'Curious beginners',text:''},captions:[{start:0,end:3,text:'Your story starts here.'}],currentProject:null};
let pendingVideoEdit=null;let db,videoURL,videoFile,videoRecorder,cancelRender=false,image=null,page='home',ytToken=null,ytExpires=0,channel=null,filter='all',dataset=null,model=null;
const designDefault={title:'MAKE SOMETHING\nEXTRAORDINARY.',subtitle:'YOUR NEXT BIG IDEA STARTS HERE',ratio:'16:9',bg:'#222b3b',color:'#ffffff',accent:'#c5a4ff',size:94,brightness:100,contrast:100,saturation:100,grayscale:0,align:'left',theme:'orbit'};
let design={...designDefault};let localJob=null,pendingSave=null;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4300);}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('buddy-x-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function dbRead(key){return new Promise((resolve,reject)=>{const r=db.transaction('workspace').objectStore('workspace').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function dbWrite(key,value){return new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
async function persist(){try{await dbWrite('state',state);$('.save-state').innerHTML='<i></i> Saved on this device';}catch(e){$('.save-state').textContent='Save failed — export a backup';toast('Unable to save. Check browser storage and export a backup.');throw e;}}
function download(name,content,type='application/json'){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.hidden=true;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function modal(title,content){$('#modal-content').innerHTML=`<div class="dialog-head"><h2>${escape(title)}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">×</button></div>${content}`;$('#modal').showModal();}
function heading(title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">YOUR CREATIVE WORKSPACE</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function toolCard(t){return `<button class="tool-card" data-page="${t.id}"><span class="arrow">↗</span><span class="tool-icon">${t.icon}</span><h3>${t.title}</h3><p>${t.desc}</p><span class="tag ${t.color}" style="margin-top:15px">${t.tag}</span></button>`;}
const starters=[{name:'A little closer to nature',type:'Design',style:'dream',title:'THE QUIET\nBETWEEN.',subtitle:'A VISUAL JOURNAL',theme:'landscape'},{name:'Ideas from another universe',type:'Design',style:'orbit',title:'THINK\nBIGGER.',subtitle:'BEYOND THE ORDINARY',theme:'orbit'},{name:'The art of starting small',type:'Design',style:'paper',title:'small steps.\nbig stories.',subtitle:'A CREATOR’S NOTEBOOK',theme:'paper'}];
function projectCard(p,isTemplate=false,i=0){return `<article class="project-card"><button class="project-cover cover-${p.style||'orbit'}" ${isTemplate?`data-template="${i}"`:`data-project="${escape(p.id)}"`} aria-label="Open ${escape(p.name)}">${p.cover?`<img src="${escape(p.cover)}" alt="">`:''}<div class="cover-title"><span class="cover-kicker">${isTemplate?'STARTER TEMPLATE':escape(p.type).toUpperCase()}</span>${escape(p.title||p.name).replace(/\n/g,'<br>')}</div><span class="tag dark">${isTemplate?'Use template ↗':escape(p.type)}</span></button><div class="project-info"><div><h3>${escape(p.name)}</h3><p>${isTemplate?'Ready to make it yours':`Edited ${new Date(p.updated).toLocaleDateString(undefined,{month:'short',day:'numeric'})} · Saved locally`}</p></div>${isTemplate?'<span class="dots">↗</span>':`<button class="dots" data-delete="${escape(p.id)}" aria-label="Delete ${escape(p.name)}">×</button>`}</div></article>`;}
function home(){return `<div>${heading('Good ideas start here.','A little inspiration. A lot of possibilities. What will you create today?',`<span class="date">${new Date().toLocaleDateString('en',{weekday:'long',month:'short',day:'numeric'})}</span>`)}<section class="hero"><div class="hero-copy"><div class="eyebrow">MEET YOUR NEW CREATIVE SIDEKICK</div><h2>From a spark of an idea<br>to <em>something extraordinary.</em></h2><p>Your canvas, your stories, your next big thing.<br>One simple space to bring it all together.</p><button class="btn dark" data-action="new">Start creating <span>↗</span></button> <button class="btn text" style="margin-left:14px" data-action="tour">Take a quick tour <span>▷</span></button></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="orb"></div><div class="art-chip chip1"><b>✧</b> A little imagination.</div><div class="art-chip chip2"><b>▧</b> Endless possibilities.</div><div class="art-chip chip3">✦ MADE BY YOU</div><span class="spark">✧</span></div></section><div class="section-head"><div><h2>What would you like to make?</h2><p>Pick a starting point. We’ll keep it simple.</p></div><button class="btn text" data-page="tools">Explore all tools <span>↗</span></button></div><div class="tools-grid">${tools.slice(0,4).map(toolCard).join('')}</div><div class="section-head"><div><h2>${state.projects.length?'Pick up where you left off':'A head start for your next idea'}</h2><p>${state.projects.length?'Your projects, right where you left them.':'A few original templates to get you going.'}</p></div>${state.projects.length?'<button class="btn text" data-page="projects">All projects ↗</button>':'<span class="tag">MADE TO BE REMIXED</span>'}</div><div class="project-grid">${state.projects.length?state.projects.slice(0,3).map(p=>projectCard(p)).join(''):starters.map((p,i)=>projectCard(p,true,i)).join('')}</div><div class="callout"><span class="round-icon">⊙</span><div><h3>Your creativity. Your channel. Connected.</h3><p>Bring your YouTube channel into your creative workflow.</p></div><button class="btn" data-page="channel">Connect YouTube <span>↗</span></button></div></div>`;}
function studio(){return `<div>${heading('Big ideas. Meet your canvas.','Create a thumbnail or design, then export a full-resolution PNG.',`<button class="btn primary" data-action="save-design">Save project ↗</button>`)}<div class="workspace-grid"><section><div class="toolbar"><button class="btn" data-action="upload-image">＋ Upload image</button><button class="btn" data-action="remove-image">Remove image</button><button class="btn" data-action="reset-design">Reset design</button><button class="btn primary" data-action="export-image">↓ Export PNG</button></div><div class="editor-stage"><canvas id="design-canvas" aria-label="Design preview"></canvas></div><div class="editor-bottom"><span id="canvas-dimensions">1280 × 720 px</span><span>Rendered on your device · No watermark</span></div><div class="notice">Start with a template, add your own image, and adjust the design. Uploads stay in this browser. The image editor uses real canvas processing.</div></section><aside class="panel"><h3>Make it yours</h3><div class="field"><label for="design-title">Headline</label><textarea id="design-title" data-design="title">${escape(design.title)}</textarea></div><div class="field"><label for="design-subtitle">Small print</label><input id="design-subtitle" data-design="subtitle" value="${escape(design.subtitle)}" maxlength="150"></div><div class="row"><div class="field"><label for="ratio">Format</label><select id="ratio" data-design="ratio">${['16:9','9:16','1:1','4:5'].map(x=>`<option ${x===design.ratio?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="theme">Background</label><select id="theme" data-design="theme">${['orbit','landscape','paper','solid'].map(x=>`<option ${x===design.theme?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="row"><div class="field"><label for="bg">Canvas</label><input id="bg" type="color" data-design="bg" value="${design.bg}"></div><div class="field"><label for="color">Text</label><input id="color" type="color" data-design="color" value="${design.color}"></div><div class="field"><label for="accent">Accent</label><input id="accent" type="color" data-design="accent" value="${design.accent}"></div></div>${[['size','Text size',30,150],['brightness','Brightness',20,180],['contrast','Contrast',20,180],['saturation','Saturation',0,200],['grayscale','Black & white',0,100]].map(([key,label,min,max])=>`<div class="field"><label for="${key}">${label}<span id="value-${key}">${design[key]}</span></label><input id="${key}" type="range" min="${min}" max="${max}" data-design="${key}" value="${design[key]}"></div>`).join('')}<div class="field"><label for="align">Text alignment</label><select id="align" data-design="align"><option value="left" ${design.align==='left'?'selected':''}>Left</option><option value="center" ${design.align==='center'?'selected':''}>Center</option></select></div></aside></div></div>`;}
function drawDesign(){const c=$('#design-canvas');if(!c)return;const sizes={'16:9':[1280,720],'9:16':[720,1280],'1:1':[1080,1080],'4:5':[1080,1350]};[c.width,c.height]=sizes[design.ratio];const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.fillStyle=design.bg;ctx.fillRect(0,0,w,h);if(image){ctx.save();ctx.filter=`brightness(${design.brightness}%) contrast(${design.contrast}%) saturate(${design.saturation}%) grayscale(${design.grayscale}%)`;const s=Math.max(w/image.width,h/image.height);ctx.drawImage(image,(w-image.width*s)/2,(h-image.height*s)/2,image.width*s,image.height*s);ctx.restore();const grad=ctx.createLinearGradient(0,0,w,0);grad.addColorStop(0,'#000a');grad.addColorStop(1,'#0000');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);}else if(design.theme==='orbit'){let g=ctx.createRadialGradient(w*.75,h*.45,0,w*.75,h*.45,w*.6);g.addColorStop(0,design.accent);g.addColorStop(1,design.bg);ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.strokeStyle='#ffffff28';ctx.lineWidth=2;for(let r=1;r<=4;r++){ctx.beginPath();ctx.ellipse(w*.76,h*.5,w*.13*r,h*.15*r,-.55,0,Math.PI*2);ctx.stroke();}g=ctx.createRadialGradient(w*.7,h*.4,1,w*.77,h*.55,w*.21);g.addColorStop(0,'#f2e6ff');g.addColorStop(.45,design.accent);g.addColorStop(1,'#1c193c');ctx.fillStyle=g;ctx.beginPath();ctx.arc(w*.77,h*.5,Math.min(w,h)*.27,0,Math.PI*2);ctx.fill();}else if(design.theme==='landscape'){const g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,'#a8b8ac');g.addColorStop(1,'#2d4b44');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.fillStyle='#f2e1b599';ctx.beginPath();ctx.arc(w*.75,h*.27,h*.09,0,7);ctx.fill();['#839a89','#526e5e','#304b43'].forEach((col,i)=>{ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(0,h);for(let x=0;x<=w;x+=10)ctx.lineTo(x,h*(.55+i*.12)+Math.sin(x/w*5+i)*h*.1);ctx.lineTo(w,h);ctx.closePath();ctx.fill();});}else if(design.theme==='paper'){ctx.fillStyle='#dfd0bd';ctx.fillRect(0,0,w,h);ctx.save();ctx.translate(w*.78,h*.55);ctx.rotate(-.2);ctx.fillStyle='#302b2422';ctx.fillRect(-w*.14+18,-h*.36+18,w*.28,h*.72);ctx.fillStyle='#fff7e7';ctx.fillRect(-w*.14,-h*.36,w*.28,h*.72);ctx.restore();}const x=design.align==='center'?w*.5:w*.07;const maxWidth=design.align==='center'?w*.87:w*.76;ctx.textAlign=design.align;ctx.fillStyle=design.color;ctx.font=`600 ${Math.round(w*.012)}px sans-serif`;ctx.fillText(design.subtitle.toUpperCase(),x,h*.22,maxWidth);const font=Math.round(design.size*w/1280);ctx.font=`800 ${font}px Manrope, sans-serif`;const lines=[];for(const line of design.title.split('\n')){let current='';for(const word of line.split(' ')){const attempt=current?current+' '+word:word;if(ctx.measureText(attempt).width>maxWidth&&current){lines.push(current);current=word;}else current=attempt;}lines.push(current);}let y=h*.43;for(const line of lines.slice(0,8)){ctx.fillText(line,x,y,maxWidth);y+=font*1.14;}ctx.fillStyle=design.accent;ctx.fillRect(design.align==='center'?w*.465:x,h*.84,w*.07,5);$('#canvas-dimensions').textContent=`${w} × ${h} px`;}
function videoPage(){return `<div>${heading('Find the story in your footage.','A focused local video trimmer. Your source file never leaves your device.')}<div class="workspace-grid"><section><div class="toolbar"><button class="btn primary" data-action="upload-video">＋ Import video</button><button class="btn" data-action="save-video">Save edit project</button></div><div class="editor-stage">${videoURL?'<video id="source-video" controls playsinline></video>':'<div class="empty" style="color:white"><div class="big-icon">▷</div><h2>Every story starts with a clip.</h2><p>Import an MP4 or WebM video to preview, set in/out points, and export a trimmed WebM.</p><button class="btn" data-action="upload-video">Choose a video ↗</button></div>'}</div><div class="timeline"><div class="row"><span class="hint">${videoFile?escape(videoFile.name):'No source selected'}</span><span class="hint" id="video-duration" style="text-align:right">00:00</span></div><div class="timeline-bar"></div><div class="row"><div class="field"><label for="trim-start">Start (seconds)</label><input type="number" id="trim-start" min="0" value="0" step="0.1"></div><div class="field"><label for="trim-end">End (seconds)</label><input type="number" id="trim-end" min="0.1" value="10" step="0.1"></div></div></div></section><aside class="panel"><h2>Your finishing touches</h2><div class="field"><label for="video-muted">Audio</label><select id="video-muted"><option value="keep">Keep source audio</option><option value="mute">Mute audio</option></select></div><button class="btn wide" data-action="preview-trim">▷ Preview selection</button><button class="btn primary wide spaced" data-action="export-video" id="render-button">↓ Export trimmed WebM</button><button class="btn wide spaced" data-action="cancel-render" id="cancel-render" hidden>Cancel export</button><div class="progress"><div id="render-progress" style="width:0%"></div></div><p class="hint" id="render-status">Export records your selected segment in real time. Keep this tab active. Maximum 5 minutes per export.</p><div class="notice">WebM export requires MediaRecorder and video capture support. It is checked before rendering. This first version supports one clip; multi-track editing and server rendering are planned.</div></aside></div></div>`;}
function scriptPage(){return `<div>${heading('A good story starts with a thought.','Shape your idea with a writing template. Edit every word and make it your own.',`<button class="btn primary" data-action="save-script">Save project ↗</button>`)}<div class="workspace-grid"><section class="panel"><div class="section-head" style="margin-top:0"><h2>Your script</h2><button class="btn" data-action="export-script">↓ Export .md</button></div><div class="field"><textarea id="script-text" class="output" style="min-height:540px" placeholder="Start writing, or use the outline builder on the right…">${escape(state.script.text)}</textarea></div><p class="hint" id="word-count">${state.script.text.split(/\s+/).filter(Boolean).length} words · Editable outline</p></section><aside class="panel"><h3>Give your story a direction</h3><div class="field"><label for="script-topic">What’s your video about?</label><textarea id="script-topic" placeholder="e.g. Making a tiny garden on my balcony">${escape(state.script.topic)}</textarea></div><div class="field"><label for="script-format">Format</label><select id="script-format">${['YouTube explainer','Tutorial','Short documentary','YouTube Short','Product review'].map(x=>`<option ${state.script.format===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="script-audience">Who’s watching?</label><input id="script-audience" value="${escape(state.script.audience)}"></div><button class="btn primary wide" data-action="outline">✧ Build my outline</button><div class="notice">This tool creates a structured template. It doesn’t call an AI model or invent facts. Research your topic, replace prompts with your story, and verify your claims.</div><h3 class="spaced">Optional local AI</h3><button class="btn wide" data-action="local-connect">Connect local engine</button><div id="local-ai-controls"></div><p class="hint">Run the included local server and Ollama on your computer. Installed models only. Not available on the hosted site.</p><button class="btn wide spaced" data-page="captions">Next: create captions →</button></aside></div></div>`;}
function captionPage(){return `<div>${heading('Make every word count.','Create timed captions and export standard SRT or WebVTT files.',`<button class="btn primary" data-action="save-captions">Save project ↗</button>`)}<div class="panel"><div class="section-head" style="margin-top:0"><h2>Your captions <span class="pill-number">${state.captions.length}</span></h2><div class="row"><button class="btn" data-format="srt">↓ SRT</button><button class="btn" data-format="vtt">↓ WebVTT</button></div></div><div class="caption-row hint"><span>Start (s)</span><span>End (s)</span><span>Caption text</span><span></span></div><div id="caption-rows">${state.captions.map((r,i)=>`<div class="caption-row" data-caption="${i}"><input aria-label="Caption ${i+1} start" type="number" min="0" step="0.1" value="${r.start}" data-key="start"><input aria-label="Caption ${i+1} end" type="number" min="0" step="0.1" value="${r.end}" data-key="end"><input aria-label="Caption ${i+1} text" value="${escape(r.text)}" data-key="text"><button data-remove-caption="${i}" aria-label="Delete caption ${i+1}">×</button></div>`).join('')}</div><button class="btn spaced" data-action="add-caption">＋ Add caption</button><div class="notice">Times are in seconds. Captions must be ordered, non-overlapping, and have an end after their start. Automatic speech transcription and translation are planned.</div></div></div>`;}
function modelsPage(){const current=state.models[0];return `<div>${heading('Small models. Yours to train.','Train a real text classifier locally, with your own labeled examples.',`<button class="btn" data-action="import-dataset">＋ Import dataset</button>`)}<div class="stats"><div class="stat"><small>TRAINING ENGINE</small><strong style="font-size:18px">Naive Bayes</strong><span class="hint">CPU · Runs in your browser</span></div><div class="stat"><small>REGISTERED VERSIONS</small><strong>${state.models.length}</strong><span class="hint">Weights stored on this device</span></div><div class="stat"><small>EXTERNAL AI SPEND</small><strong>$0</strong><span class="hint">No paid API calls implemented</span></div></div><div class="workspace-grid"><section class="panel"><h2>Your model registry</h2>${state.models.length?state.models.map((m,i)=>`<div class="list-row"><span class="tool-icon" style="margin:0">⬡</span><div><h3>${escape(m.name)} <span class="tag purple">v${state.models.length-i}</span></h3><p>${m.metrics.total} held-out examples · ${(m.metrics.accuracy*100).toFixed(1)}% test accuracy</p><p style="margin-top:5px">Baseline: ${(m.baseline*100).toFixed(1)}% · Source: ${escape(m.origin)}</p></div><button class="btn" data-model-export="${i}">↓</button><button class="btn danger" data-model-delete="${i}" aria-label="Delete model version">×</button></div>`).join(''):'<div class="empty"><div class="big-icon">⬡</div><h2>Your first model starts with your data.</h2><p>Classify topics, content formats, or your own categories. Import labeled examples, train locally, and evaluate on held-out data.</p><button class="btn" data-action="sample-dataset">↓ Download dataset example</button></div>'}<div class="notice green">No private media is used for training. Only the JSON dataset you explicitly import is processed. Training runs when you press the button.</div>${current?`<div class="field"><label for="inference-text">Try the latest model</label><textarea id="inference-text" placeholder="Write text to predict its category…"></textarea></div><button class="btn primary" data-action="predict">Run local inference ↗</button><div id="prediction" role="status"></div><details class="spaced"><summary class="hint">Evaluation report</summary><pre>${escape(JSON.stringify({metrics:current.metrics,validation:current.validation,split:current.split,baseline:current.baseline},null,2))}</pre></details>`:''}</section><aside class="panel"><h3>Train a new version</h3><div class="field"><label for="model-name">Model name</label><input id="model-name" value="My topic classifier" maxlength="80"></div><div class="field"><label for="dataset-origin">Dataset origin / rights</label><textarea id="dataset-origin" placeholder="e.g. My original examples, approved for training"></textarea></div><div class="field"><label for="training-license"><input type="checkbox" id="training-license"> I have the right to train on this data</label></div><button class="btn wide" data-action="import-dataset">＋ Choose JSON dataset</button><p id="dataset-info" class="hint">${dataset?`${dataset.length} valid unique examples ready`:'20–10,000 rows · text + label fields'}</p><button class="btn primary wide spaced" data-action="train-model" id="train-button">Train & evaluate ↗</button><div class="progress"><div id="train-progress" style="width:0%"></div></div><p id="train-status" class="hint">Stratified split · 70% train / 15% validation / 15% test (rounded per label). Fixed random seed.</p><div class="notice">Image, video, speech and music generation are not installed. They require licensed weights, inference adapters and suitable hardware. No foundation models have been trained.</div></aside></div></div>`;}
function channelPage(){return `<div>${heading('Your next chapter starts with your channel.','Connect through Google to read your own YouTube channel data.')}<div class="workspace-grid"><section class="panel">${channel?`<div class="section-head" style="margin-top:0"><div><span class="tag green">CONNECTED FOR THIS SESSION</span><h2 style="margin-top:12px">${escape(channel.snippet.title)}</h2><p>${escape(channel.snippet.description?.slice(0,180)||'Your YouTube channel')}</p></div><button class="btn" data-action="disconnect-youtube">Disconnect</button></div><div class="stats"><div class="stat"><small>SUBSCRIBERS</small><strong>${channel.statistics.hiddenSubscriberCount?'Hidden':Number(channel.statistics.subscriberCount).toLocaleString()}</strong></div><div class="stat"><small>TOTAL VIEWS</small><strong>${Number(channel.statistics.viewCount).toLocaleString()}</strong></div><div class="stat"><small>VIDEOS</small><strong>${Number(channel.statistics.videoCount).toLocaleString()}</strong></div></div><div class="notice green">Live data from YouTube Data API. Session tokens stay in memory and expire; refresh the connection when needed. No upload permission is requested.</div><button class="btn" data-action="refresh-youtube">Refresh channel</button>`:`<div class="empty"><div class="big-icon" style="color:#c77970">▷</div><span class="tag amber">ONE-TIME GOOGLE SETUP NEEDED</span><h2 style="margin-top:18px">A little closer to your audience.</h2><p>See your real subscriber count, total views and published videos. Your channel stays yours — connection uses Google’s official consent screen.</p><button class="btn primary" data-action="connect-youtube">Connect with Google ↗</button><p class="hint">Read-only access. No passwords. No automatic publishing.</p></div>`}<div id="youtube-error" class="hint" role="alert"></div></section><aside class="panel"><h3>Connection settings</h3><div class="field"><label for="google-client">Google OAuth client ID</label><input id="google-client" placeholder="…apps.googleusercontent.com" value="${escape(state.settings.clientId)}"><small>A public Web client ID, never a client secret.</small></div><button class="btn wide" data-action="save-google">Save client ID</button><div class="setup-steps"><div class="setup-step"><div><strong>Create your Google project</strong><p>Enable YouTube Data API v3 and configure the OAuth consent screen with your app name and test users.</p></div></div><div class="setup-step"><div><strong>Add this site’s origin</strong><p>Create a Web application OAuth client. Authorized JavaScript origin:<br><code>${escape(location.origin)}</code></p></div></div><div class="setup-step"><div><strong>Connect your channel</strong><p>Save the public client ID, then connect and approve youtube.readonly. A Google review may be required before public use.</p></div></div></div><a class="btn wide" href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener">Open Google Cloud Console ↗</a></aside></div><div class="notice">Channel authorization is separate from app sign-in. Google account login, YouTube Analytics reports, background refresh, channel uploads and scheduled publishing are not enabled in this release.</div></div>`;}
function projectsPage(){const projects=state.projects.filter(p=>filter==='all'||p.type.toLowerCase()===filter);return `<div>${heading('A home for all your ideas.','Projects are saved in this browser. Export a backup to keep a portable copy.',`<button class="btn primary" data-action="new">＋ New creation</button>`)}<div class="section-head"><div class="filter-tabs">${['all','design','script','captions','video'].map(f=>`<button data-filter="${f}" class="${filter===f?'active':''}">${f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div><button class="btn" data-action="backup">↓ Export backup</button></div>${projects.length?`<div class="project-grid">${projects.map(p=>projectCard(p)).join('')}</div>`:'<div class="panel empty"><div class="big-icon">▤</div><h2>A blank page. A fresh beginning.</h2><p>Create a design, script or caption project. Save it, and you’ll find it here.</p><button class="btn primary" data-action="new">Start your first project ↗</button></div>'}<div class="section-head"><h2>Start with a little inspiration</h2></div><div class="project-grid">${starters.map((p,i)=>projectCard(p,true,i)).join('')}</div></div>`;}
function toolsPage(){return `<div>${heading('Your creative toolkit.','Focused tools that do real work. Choose where you want to start.')}<div class="tools-grid tool-catalog">${tools.map(toolCard).join('')}</div><div class="notice">Available today: canvas design, local video trimming, script templates, timed captions, project storage, and a trainable text classifier. AI image/video generation, VFX, 3D and 24/7 automation remain planned. <a href="/tool-catalog.json" download style="text-decoration:underline">Download the full feature tracker ↗</a></div></div>`;}
function directorPage(){return `<div>${heading('An idea is just the beginning.','A simple, human-guided production plan. One manageable step at a time.')}<div class="hero" style="min-height:190px"><div class="hero-copy" style="width:90%"><div class="eyebrow">YOUR PRODUCTION COMPASS</div><h2 style="font-size:30px">Make a little progress.<br><em>Make something you’re proud of.</em></h2><p>Follow the four steps below. Each opens a working tool.</p></div></div><div class="workflow-grid">${[['01','Find your story','Shape your idea with an editable outline.','scripts','Write a script'],['02','Create the first impression','Design a thumbnail that tells your story.','studio','Design a thumbnail'],['03','Cut to what matters','Import footage and trim a focused clip.','video','Edit your video'],['04','Bring everyone along','Add timed captions. Export and review.','captions','Create captions']].map(([n,t,d,id,b])=>`<section class="workflow-step"><b>${n}</b><h3>${t}</h3><p>${d}</p><button class="btn" data-page="${id}">${b} ↗</button></section>`).join('')}</div><div class="notice">You’re in control of every step. This is a production checklist; autonomous agents, background execution and automatic publishing are planned.</div></div>`;}
function settingsPage(){return `<div>${heading('A studio that feels like yours.','Your data, connections and setup — clearly explained.')}<div class="workspace-grid"><section class="panel"><h2>Workspace & data</h2><div class="list-row"><div><h3>Local-first storage</h3><p>${state.projects.length} projects · ${state.models.length} trained model versions · IndexedDB</p></div><span class="tag green">ON THIS DEVICE</span></div><div class="notice">Browser data is not a cloud backup. Clearing site data removes projects and models. Export regularly. Original video files need to be reselected when reopening an edit.</div><div class="toolbar"><button class="btn primary" data-action="backup">↓ Export workspace backup</button><button class="btn" data-action="restore">↑ Restore backup</button></div><h3 class="spaced">Publishing & infrastructure</h3><div class="list-row"><div><h3>Hosted frontend</h3><p>Published through Sites. This release runs its tools in your browser.</p></div><span class="tag green">STATIC APP</span></div><div class="list-row"><div><h3>youtubebuddy.in</h3><p>Custom-domain and GoDaddy access have not been configured.</p></div><span class="tag amber">NOT CONNECTED</span></div><div class="list-row"><div><h3>24/7 workers and model inference</h3><p>No always-on server, GPU workers or large generative models provisioned.</p></div><span class="tag amber">NOT INSTALLED</span></div><div class="list-row"><div><h3>Google app sign-in</h3><p>Separate from channel OAuth. Not configured in this local-first release.</p></div><span class="tag amber">PLANNED</span></div><a class="btn spaced" href="/source.zip" download>↓ Download full source</a> <a class="btn spaced" href="/RELEASE-UPGRADE.md" download>↓ Setup guide</a> <a class="btn spaced" href="/RELEASE-UPGRADE.md" download>↓ Verification report</a> <a class="btn spaced" href="/tool-catalog.json" download>↓ Feature inventory</a></section><aside class="panel"><h3>Free by design. Honest by default.</h3><p class="hint">The tools in this release process on your device. No paid AI endpoints are connected. Availability of hosting and APIs depends on their providers; free 24/7 compute cannot be guaranteed.</p><div class="notice green">Files are not sent to our server for editing or training. YouTube requests go directly to Google after your consent.</div><button class="btn wide" data-page="channel">YouTube setup ↗</button><h3 class="spaced">Accessibility</h3><p class="hint">Keyboard navigation, responsive layouts, visible focus and reduced-motion support are built in. Press Ctrl/⌘ K to find a tool.</p><h3 class="spaced">Privacy</h3><p class="hint">The page loads fonts from Google and the Google Identity library. Channel access tokens remain in memory, not in project backups. Disconnect to revoke the current grant.</p></aside></div></div>`;}
async function navigate(id){if(videoRecorder?.state==='recording'){toast('Finish or cancel the video export before leaving.');return;}const previousVideo=$('#source-video');if(previousVideo)previousVideo.pause();page=id;location.hash=id;$('#sidebar').classList.remove('open');$('#navigation').innerHTML=nav.map(([id,icon,label])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}"><span>${icon}</span>${label}${id==='models'?'<span class="pill">LOCAL</span>':''}</button>`).join('');$('#page-label').textContent=nav.find(n=>n[0]===id)?.[2]||({scripts:'Script workspace',captions:'Caption creator',settings:'Settings'}[id])||'Overview';const render={home,studio,video:videoPage,scripts:scriptPage,captions:captionPage,models:modelsPage,channel:channelPage,projects:projectsPage,tools:toolsPage,director:directorPage,settings:settingsPage}[id]||home;$('#main').innerHTML=render();if(id==='studio')drawDesign();if(id==='video'&&videoURL){const v=$('#source-video');v.src=videoURL;v.onloadedmetadata=()=>{if(Number.isFinite(v.duration)){$('#trim-end').value=Math.min(v.duration,300).toFixed(2);if(pendingVideoEdit&&pendingVideoEdit.source===videoFile?.name){$('#trim-start').value=pendingVideoEdit.start;$('#trim-end').value=pendingVideoEdit.end;$('#video-muted').value=pendingVideoEdit.muted;pendingVideoEdit=null;}$('#video-duration').textContent=`${v.duration.toFixed(1)} seconds`;}};}window.scrollTo(0,0);}
async function saveProject(type,data,cover){const existing=state.projects.find(p=>p.id===state.currentProject&&p.type===type);pendingSave={type,data,cover,id:existing?.id};const name=existing?.name||({Design:'Untitled design',Script:state.script.topic||'Untitled script',Captions:'My captions',Video:videoFile?.name||'Video edit'}[type]);modal('Give your idea a home.',`<div class="field"><label for="project-name">Project name</label><input id="project-name" value="${escape(name)}" maxlength="100" autofocus></div><p class="hint" style="margin-bottom:20px">Saved on this device. Export a backup to keep a portable copy.</p><button class="btn primary wide" data-action="confirm-save">Save project ↗</button>`);$('#project-name').focus();}
async function confirmSave(){if(!pendingSave)return;const name=$('#project-name').value.trim();if(!name)throw Error('Give your project a name.');const p={...pendingSave,id:pendingSave.id||(globalThis.crypto?.randomUUID?.()||'project-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),name,updated:Date.now()};state.projects=state.projects.filter(x=>x.id!==p.id);state.projects.unshift(p);state.currentProject=p.id;await persist();pendingSave=null;$('#modal').close();toast('Project saved on this device.');}
async function loadProject(id){const p=state.projects.find(p=>p.id===id);if(!p)return;state.currentProject=p.id;if(p.type==='Design'){design={...designDefault,...p.data.design};image=null;if(p.data.image){image=await imageFrom(p.data.image);}navigate('studio');}if(p.type==='Script'){state.script=p.data;navigate('scripts');}if(p.type==='Captions'){state.captions=p.data;navigate('captions');}if(p.type==='Video'){pendingVideoEdit=p.data;navigate('video');if(p.data.source!==videoFile?.name)toast('Reselect the original video to reopen this edit.');else{$('#trim-start').value=p.data.start;$('#trim-end').value=p.data.end;}}}
function imageFrom(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Could not decode that image.'));im.src=src;});}
function imageData(){if(!image)return null;const c=document.createElement('canvas'),s=Math.min(1,2400/Math.max(image.width,image.height));c.width=image.width*s;c.height=image.height*s;c.getContext('2d').drawImage(image,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.9);}
function smallCover(){const c=document.createElement('canvas');c.width=480;c.height=270;c.getContext('2d').drawImage($('#design-canvas'),0,0,480,270);return c.toDataURL('image/jpeg',.75);}
function captureScript(){if($('#script-text'))state.script={topic:$('#script-topic').value,format:$('#script-format').value,audience:$('#script-audience').value,text:$('#script-text').value};}
function sampleDataset(){const groups={technology:['Reviewing a new laptop for programming','How to build your first website','The best keyboard for developers','Testing smartphone camera features','How computer processors work','Learning Python with simple projects','A guide to desktop graphics cards','Setting up a secure home network','Using Linux on an old computer','Understanding software version control','Explaining artificial intelligence basics','Choosing a microphone for streaming'],cooking:['Baking a loaf of sourdough bread','How to make tomato pasta sauce','A quick recipe for vegetable curry','Preparing fresh salad for lunch','The secret to fluffy pancakes','Roasting vegetables with olive oil','Making homemade pizza dough','A simple guide to cooking rice','Creating a delicious chocolate cake','Trying a new soup recipe','Traditional spices for Indian food','Preparing healthy breakfast smoothies'],travel:['Hiking through the mountain valley','A weekend trip to the beach','Exploring historic temples in Jaipur','Packing a backpack for a holiday','A guide to visiting quiet islands','Taking a train across the country','Camping beside a mountain lake','Discovering local markets abroad','Planning a budget road trip','Finding a scenic walking trail','Touring the ancient city streets','Photographing wildlife on safari']};return Object.entries(groups).flatMap(([label,texts])=>texts.map(text=>({text,label})));}
async function train(){if(!dataset)throw Error('Import a labeled dataset first.');const origin=$('#dataset-origin').value.trim(),name=$('#model-name').value.trim();if(!name||!origin||!$('#training-license').checked)throw Error('Add a model name, dataset origin, and confirm training rights.');$('#train-button').disabled=true;$('#train-status').textContent='Validating and splitting your dataset…';await new Promise(r=>setTimeout(r,30));try{const rows=validateDataset(dataset),split=splitDataset(rows);$('#train-progress').style.width='30%';const candidates=[.5,1,2].map(alpha=>{const weights=trainClassifier(split.train,alpha);return {weights,validation:evaluate(weights,split.validation)};});candidates.sort((a,b)=>b.validation.accuracy-a.validation.accuracy);const best=candidates[0];const metrics=evaluate(best.weights,split.test);const majority=Object.entries(best.weights.docs).sort((a,b)=>b[1]-a[1])[0][0];const baseline=split.test.filter(r=>r.label===majority).length/split.test.length;const record={name,origin,rights:'User confirmed training rights',created:new Date().toISOString(),license:'User-supplied dataset; rights determined by recorded source',weights:best.weights,metrics,validation:best.validation,baseline,split:{train:split.train.length,validation:split.validation.length,test:split.test.length,seed:42},deployed:false};state.models.unshift(record);await persist();toast(`Trained locally. Test accuracy: ${(metrics.accuracy*100).toFixed(1)}% on ${metrics.total} examples.`);navigate('models');}finally{if($('#train-button'))$('#train-button').disabled=false;}}
async function fetchChannel(){if(!ytToken||Date.now()>ytExpires){ytToken=null;channel=null;throw Error('Your connection has expired. Connect again to refresh access.');}const r=await fetch('https://www.googleapis.com/youtube/v3/channels?part=snippet,statistics&mine=true',{headers:{Authorization:`Bearer ${ytToken}`}});const data=await r.json();if(!r.ok)throw Error(data.error?.message||'Could not read channel data.');if(!data.items?.length)throw Error('No YouTube channel found for this Google account.');channel=data.items[0];navigate('channel');}
function connectYT(){const id=state.settings.clientId;if(!id.endsWith('.apps.googleusercontent.com'))throw Error('Save a valid Google OAuth Web client ID first.');if(!window.google?.accounts?.oauth2)throw Error('Google Identity did not load. Check your connection or content blocker.');google.accounts.oauth2.initTokenClient({client_id:id,scope:'https://www.googleapis.com/auth/youtube.readonly',error_callback:e=>toast(e.message||'Google connection was closed.'),callback:async response=>{if(response.error){toast(response.error_description||response.error);return;}ytToken=response.access_token;ytExpires=Date.now()+Number(response.expires_in||3600)*1000;try{await fetchChannel();}catch(e){toast(e.message);}}}).requestAccessToken({prompt:'consent'});}
async function seek(v,t){if(Math.abs(v.currentTime-t)<.03)return;await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{v.removeEventListener('seeked',done);reject(Error('Video seek timed out.'));},10000);const done=()=>{clearTimeout(timeout);resolve();};v.addEventListener('seeked',done,{once:true});v.currentTime=t;});}
function getTrim(){const v=$('#source-video');if(!v||!Number.isFinite(v.duration))throw Error('Import a supported video first.');const start=Number($('#trim-start').value),end=Number($('#trim-end').value);if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start||end>v.duration+.01||end-start>300)throw Error('Choose valid start/end times within the video, up to 300 seconds.');return{v,start,end};}
async function renderVideo(){const {v,start,end}=getTrim();v.ontimeupdate=null;const capture=v.captureStream||v.mozCaptureStream;if(!window.MediaRecorder||!capture)throw Error('This browser cannot capture video. Try a current Chromium browser.');const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw Error('WebM encoding is not supported in this browser.');v.pause();await seek(v,start);const stream=capture.call(v);if(!stream.getVideoTracks().length)throw Error('The video track is unavailable. Play the clip once, pause, then retry.');if($('#video-muted').value==='mute')stream.getAudioTracks().forEach(t=>{stream.removeTrack(t);t.stop();});const chunks=[];cancelRender=false;videoRecorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:5000000});const recorded=new Promise((resolve,reject)=>{videoRecorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};videoRecorder.onstop=resolve;videoRecorder.onerror=()=>reject(Error('Browser recording failed.'));});$('#render-button').disabled=true;$('#cancel-render').hidden=false;$('#render-status').textContent='Exporting in real time. Keep this tab active…';videoRecorder.start(250);let timer;try{await v.play();await new Promise((resolve,reject)=>{const began=Date.now();timer=setInterval(()=>{const progress=Math.min(100,(v.currentTime-start)/(end-start)*100);$('#render-progress').style.width=`${progress}%`;if(cancelRender||v.currentTime>=end||v.ended)resolve();if(Date.now()-began>(end-start)*1000+30000)reject(Error('Export stalled. Please retry with the tab active.'));},25);});clearInterval(timer);v.pause();videoRecorder.stop();await recorded;if(!cancelRender){if(!chunks.length)throw Error('No video frames were recorded.');download('buddy-x-trim.webm',new Blob(chunks,{type:mime}));toast('Trimmed WebM exported.');$('#render-status').textContent='Export complete. Review the downloaded file before publishing.';}else $('#render-status').textContent='Export cancelled. No file saved.';}finally{clearInterval(timer);v.pause();if(videoRecorder?.state==='recording')videoRecorder.stop();stream.getTracks().forEach(t=>t.stop());videoRecorder=null;$('#render-button').disabled=false;$('#cancel-render').hidden=true;}}
function search(){modal('Find your next tool',`<input class="search-input" id="tool-search" placeholder="Search tools…" autofocus><div id="search-results" style="margin-top:15px"></div>`);const update=()=>{const q=$('#tool-search').value.toLowerCase();$('#search-results').innerHTML=tools.filter(t=>(t.title+' '+t.desc).toLowerCase().includes(q)).map(t=>`<button class="search-result" data-page="${t.id}"><span class="tool-icon" style="margin:0">${t.icon}</span><span>${t.title}<small>${t.desc}</small></span></button>`).join('')||'<p class="hint">No matching tools. Try “video”, “caption” or “model”.</p>';};$('#tool-search').oninput=update;update();$('#tool-search').focus();}
async function localConnect(){const r=await fetch('/api/models');if(!r.ok){let msg='Run python local/server.py, then open http://localhost:8080 to use your local engine.';try{msg=(await r.json()).error||msg;}catch{}throw Error(msg);}const data=await r.json();if(!data.models?.length)throw Error('No local models installed. Install a licensed model in Ollama first.');$('#local-ai-controls').innerHTML=`<div class="field spaced"><label for="local-model">Installed model</label><select id="local-model">${data.models.map(m=>`<option>${escape(m)}</option>`).join('')}</select></div><button class="btn primary wide" data-action="local-generate" id="local-generate">Generate script locally ↗</button><p id="local-job-status" class="hint"></p>`;}
async function localGenerate(){captureScript();if(!state.script.topic.trim())throw Error('Enter your video topic first.');if(state.script.text&&!confirm('Replace the current script with local AI output?'))return;const r=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:$('#local-model').value,prompt:`Write an editable ${state.script.format} script for ${state.script.audience} about: ${state.script.topic}. Include a hook, scene cues, key points and a closing. Do not invent statistics. Mark claims that need sources.`})});const job=await r.json();if(!r.ok)throw Error(job.error||'Could not start local generation.');localJob=job.id;$('#local-generate').disabled=true;$('#local-job-status').textContent='Queued locally. This job is stored in local/data/jobs.sqlite3.';const jobPage=page;const interval=setInterval(async()=>{try{const result=await (await fetch('/api/jobs/'+job.id)).json();if($('#local-job-status'))$('#local-job-status').textContent='Local job: '+result.status;if(['succeeded','failed','interrupted'].includes(result.status)){clearInterval(interval);localJob=null;if(result.status==='succeeded'){state.script.text=result.result;await persist();if(page==='scripts')navigate('scripts');toast('Local model generated a script. Review facts before use.');}else toast(result.error||'Local generation failed.');if($('#local-generate'))$('#local-generate').disabled=false;}}catch{clearInterval(interval);toast('Local server disconnected. Job history remains in the SQLite database.');if($('#local-generate'))$('#local-generate').disabled=false;}},1500);}
const actions={'confirm-save':confirmSave,'local-connect':localConnect,'local-generate':localGenerate,new:()=>modal('What will you create?',`<p class="hint" style="margin-bottom:18px">Start small. You can always make it bigger.</p>${tools.slice(0,4).map(t=>`<button class="search-result" data-new="${t.id}"><span class="tool-icon" style="margin:0">${t.icon}</span><span>${t.title}<small>${t.desc}</small></span><span style="margin-left:auto">↗</span></button>`).join('')}`),close:()=>$('#modal').close(),tour:()=>modal('Your first creation, in three steps.',`<span class="tour-step">WELCOME TO BUDDY X</span><div class="setup-steps"><div class="setup-step"><div><strong>Pick one thing to make</strong><p>Start with a thumbnail, script, video clip or captions.</p></div></div><div class="setup-step"><div><strong>Make it yours</strong><p>Upload your media or use a starter. Adjust the controls and preview the result.</p></div></div><div class="setup-step"><div><strong>Save. Export. Share.</strong><p>Save projects on your device and download your finished work. Export a workspace backup regularly.</p></div></div></div><button class="btn primary wide" data-new="studio">Let’s make a thumbnail ↗</button>`),'upload-image':()=>$('#image-upload').click(),'remove-image':()=>{image=null;drawDesign();},'reset-design':()=>{design={...designDefault};image=null;navigate('studio');},'export-image':()=>{const c=$('#design-canvas');c.toBlob(b=>{if(b){download('buddy-x-design.png',b);toast('Full-resolution PNG exported.');}},'image/png');},'save-design':()=>saveProject('Design',{design:{...design},image:imageData()},smallCover()),'upload-video':()=>$('#video-upload').click(),'preview-trim':async()=>{const {v,start,end}=getTrim();await seek(v,start);v.ontimeupdate=()=>{if(v.currentTime>=end){v.pause();v.ontimeupdate=null;}};await v.play();},'export-video':renderVideo,'cancel-render':()=>{cancelRender=true;},'save-video':()=>{const {start,end}=getTrim();return saveProject('Video',{source:videoFile.name,start,end,muted:$('#video-muted').value});},outline:async()=>{captureScript();if(state.script.text&&!confirm('Replace the current script with a new outline?'))return;state.script.text=buildOutline(state.script.topic,state.script.format,state.script.audience);await persist();navigate('scripts');},'save-script':()=>{captureScript();return saveProject('Script',{...state.script});},'export-script':()=>{captureScript();if(!state.script.text.trim())throw Error('Write a script first.');download('buddy-x-script.md',state.script.text,'text/markdown');},'save-captions':()=>{captionsExport(state.captions);return saveProject('Captions',structuredClone(state.captions));},'add-caption':async()=>{const last=Number(state.captions.at(-1)?.end||0);state.captions.push({start:last,end:last+3,text:''});await persist();navigate('captions');},'import-dataset':()=>$('#dataset-upload').click(),'sample-dataset':()=>download('example-dataset.json',JSON.stringify(sampleDataset(),null,2)),'train-model':train,predict:()=>{$('#prediction').className='model-result';$('#prediction').textContent=`Predicted category: ${predict(state.models[0].weights,$('#inference-text').value)} · Experimental classifier; validate before production use.`;},'connect-youtube':connectYT,'save-google':async()=>{const id=$('#google-client').value.trim();if(id&&!id.endsWith('.apps.googleusercontent.com'))throw Error('Enter a Google OAuth Web client ID, not a client secret.');state.settings.clientId=id;await persist();toast('Public client ID saved. You can connect your channel.');},'refresh-youtube':fetchChannel,'disconnect-youtube':()=>{if(ytToken&&window.google?.accounts?.oauth2){google.accounts.oauth2.revoke(ytToken,()=>toast('Google channel permission revoked.'));}ytToken=null;ytExpires=0;channel=null;navigate('channel');},backup:()=>download('buddy-x-workspace-backup.json',JSON.stringify({schema:1,exportedAt:new Date().toISOString(),...state,settings:{clientId:state.settings.clientId}})),restore:()=>$('#backup-upload').click()};
document.addEventListener('click',async e=>{const b=e.target.closest('button,a[data-page]');if(!b)return;try{if(b.dataset.page){if($('#modal').open)$('#modal').close();if(page==='scripts'){captureScript();await persist();}navigate(b.dataset.page);}if(b.dataset.action)await actions[b.dataset.action]?.();if(b.dataset.new){state.currentProject=null;if(b.dataset.new==='studio'){design={...designDefault};image=null;}$('#modal').close();navigate(b.dataset.new);}if(b.dataset.template!==undefined){const t=starters[Number(b.dataset.template)];state.currentProject=null;image=null;design={...designDefault,title:t.title,subtitle:t.subtitle,theme:t.theme,...(t.theme==='paper'?{color:'#473c35',accent:'#a56b42'}:{})};navigate('studio');}if(b.dataset.project)await loadProject(b.dataset.project);if(b.dataset.delete&&confirm('Delete this project from this device?')){state.projects=state.projects.filter(p=>p.id!==b.dataset.delete);await persist();navigate(page);}if(b.dataset.filter){filter=b.dataset.filter;navigate('projects');}if(b.dataset.format){download(`captions.${b.dataset.format}`,captionsExport(state.captions,b.dataset.format),'application/octet-stream');toast('Caption file exported.');}if(b.dataset.removeCaption!==undefined){state.captions.splice(Number(b.dataset.removeCaption),1);await persist();navigate('captions');}if(b.dataset.modelExport!==undefined)download('buddy-x-trained-model.json',JSON.stringify(state.models[Number(b.dataset.modelExport)],null,2));if(b.dataset.modelDelete!==undefined&&confirm('Delete this trained model version?')){state.models.splice(Number(b.dataset.modelDelete),1);await persist();navigate('models');}}catch(err){toast(err.message||'Something went wrong. Please try again.');}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.design){const key=t.dataset.design;design[key]=t.type==='range'?Number(t.value):t.value;const label=$(`#value-${key}`);if(label)label.textContent=t.value;drawDesign();}if(t.closest('[data-caption]')){const i=Number(t.closest('[data-caption]').dataset.caption);state.captions[i][t.dataset.key]=t.type==='number'?Number(t.value):t.value;persist().catch(()=>{});}if(t.id==='script-text'||t.id==='script-topic'||t.id==='script-audience'||t.id==='script-format'){captureScript();if($('#word-count'))$('#word-count').textContent=`${state.script.text.split(/\s+/).filter(Boolean).length} words · Editable outline`;clearTimeout(window.scriptSave);window.scriptSave=setTimeout(()=>persist().catch(()=>{}),500);}});
$('#image-upload').onchange=async e=>{const f=e.target.files[0];try{if(!f)return;if(f.size>25*1024*1024)throw Error('Choose an image under 25 MB.');const url=URL.createObjectURL(f);try{image=await imageFrom(url);}finally{URL.revokeObjectURL(url);}if(page!=='studio')navigate('studio');else drawDesign();toast('Image loaded. Adjust the design to make it yours.');}catch(err){toast(err.message);}e.target.value='';};
$('#video-upload').onchange=e=>{const f=e.target.files[0];if(f){if(f.size>1024**3){toast('Choose a video under 1 GB for this browser editor.');return;}if(videoURL)URL.revokeObjectURL(videoURL);videoFile=f;videoURL=URL.createObjectURL(f);navigate('video');}e.target.value='';};
$('#dataset-upload').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('Dataset must be under 10 MB.');dataset=validateDataset(JSON.parse(await f.text()));if(page!=='models')navigate('models');else $('#dataset-info').textContent=`${dataset.length} valid unique examples · ${new Set(dataset.map(r=>r.label)).size} labels`;toast('Dataset validated. Add its origin and confirm training rights.');}catch(err){dataset=null;toast(err.message);}e.target.value='';};
$('#backup-upload').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100*1024*1024)throw Error('Backup too large (maximum 100 MB).');const b=validateBackup(JSON.parse(await f.text()));if(!confirm('Restore this backup? It replaces projects and models currently saved on this device.'))return;state={projects:b.projects,models:b.models,captions:b.captions,script:b.script,currentProject:null,settings:{clientId:typeof b.settings?.clientId==='string'?b.settings.clientId:''}};await persist();navigate('projects');toast('Workspace restored.');}catch(err){toast(err.message);}e.target.value='';};
$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#search-open').onclick=search;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search();}if(e.key.toLowerCase()==='n'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open)actions.new();});window.addEventListener('hashchange',()=>{const id=location.hash.slice(1)||'home';if(id!==page)navigate(id);});window.addEventListener('beforeunload',e=>{if(videoRecorder?.state==='recording'){e.preventDefault();e.returnValue='';}});
try{db=await openDB();const saved=await dbRead('state');if(saved)state={...state,...saved};await document.fonts.ready;await navigate(location.hash.slice(1)||'home');}catch(e){$('#main').innerHTML='<div class="panel empty"><h2>Your browser storage is unavailable.</h2><p>Allow site storage or use a regular browsing window, then reload. No work has been saved.</p></div>';}
